    name: { de: "Historische Schmieden von Sindou", hu: "Sindou történelmi kovácsműhelyei", ro: "Fierăriile istorice din Sindou", en: "Sindou Historical Forges"},
    image: "/poi-images/sindou-historical-forges-history-v2.webp",
    description: { de: "Alte Stätten der Eisenverarbeitung, die für lokale Werkzeuge und Waffen entscheidend waren.", hu: "Régi vasfeldolgozó helyek, amelyek kulcsfontosságúak voltak a helyi szerszámok és fegyverek szempontjából.", ro: "Vechi situri de prelucrare a fierului cruciale pentru uneltele și armele locale.", en: "Old iron processing sites crucial for local tools and weapons." },
